<?php use App\Core\Authorization; use App\Services\ContentWorkspaceService; $canManage=Authorization::can($admin,'content.manage'); $statuses=['published'=>'منتشرشده','draft'=>'پیش‌نویس','archived'=>'بایگانی']; ?>
<header class="admin-page-head"><div><span class="eyebrow">مدیریت محتوای منتوریس</span><h1><?= e($workspace['label']) ?></h1><p><?= e($workspace['hint']) ?></p></div><?php if($canManage): ?><a class="btn btn--primary" href="<?= e($workspacePath) ?>/new"><?= icon($workspace['icon']) ?> <?= e($workspace['singular']) ?> جدید</a><?php endif; ?></header>
<nav class="content-workspace-nav" aria-label="بخش‌های محتوا"><?php foreach(ContentWorkspaceService::MODULES as $slug=>$module): ?><a href="/admin/<?= e($slug) ?>" class="<?= $workspace['type']===$module['type']?'is-active':'' ?>" <?= $workspace['type']===$module['type']?'aria-current="page"':'' ?>><?= e($module['label']) ?></a><?php endforeach; ?></nav>
<section class="admin-info-grid" aria-label="آمار این بخش"><?php foreach($statuses as $status=>$label): ?><article><span><?= e($label) ?></span><strong><?= number_format($counts[$status]) ?></strong><small>در این بخش</small></article><?php endforeach; ?></section>
<section class="admin-panel mt-8"><header><h2>فهرست <?= e($workspace['label']) ?></h2><span><?= number_format($pagination['total']) ?> نتیجه</span></header>
<form class="admin-filters" method="get"><label><span class="sr-only">جست‌وجو</span><input class="form-control" name="q" value="<?= e($filters['query']) ?>" placeholder="جست‌وجوی عنوان یا نامک"></label><label><span class="sr-only">وضعیت</span><select class="form-select" name="status"><option value="all">همه وضعیت‌ها</option><?php foreach($statuses as $status=>$label): ?><option value="<?= e($status) ?>" <?= $filters['status']===$status?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="btn btn--secondary">جست‌وجو</button><a class="btn btn--ghost" href="<?= e($workspacePath) ?>">پاک‌کردن فیلتر</a></form>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>عنوان</th><th>وضعیت</th><th>ترجمه‌ها</th><th>ویرایشگر</th><th>آخرین ویرایش</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= e($item['title'] ?: $item['slug']) ?></strong><small class="table-sub ltr"><?= e($item['slug']) ?></small></td><td><?= e($statuses[$item['status']] ?? $item['status']) ?></td><td><?= (int)$item['translation_count'] ?> از ۴</td><td><?= e($item['author_name'] ?? '—') ?></td><td><time data-local-date="<?= e(str_replace(' ','T',$item['updated_at']).'Z') ?>"><?= e($item['updated_at']) ?></time></td><td><?php if($canManage): ?><a class="btn btn--ghost btn--sm" href="<?= e($workspacePath.'/'.$item['id']) ?>/edit">ویرایش <?= icon('arrow-left') ?></a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="6"><p class="admin-empty-row">موردی پیدا نشد. از دکمهٔ بالای صفحه، <?= e($workspace['singular']) ?> جدید بسازید.</p></td></tr><?php endif; ?></tbody></table></div>
<?php require view_path('components/admin/pagination.php'); ?></section>
